import { test, expect } from '@playwright/test';

test.describe('Search Filter Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search'); // Replace with the actual URL of the search page
  });

  test('should apply filters correctly', async ({ page }) => {
    await page.getByLabel('Category').selectOption('Electronics');
    await page.getByLabel('Brand').selectOption('Brand A');
    await page.getByRole('button', { name: 'Apply Filters' }).click();

    const filterSummary = await page.getByRole('heading', { name: 'Applied Filters' });
    await expect(filterSummary).toBeVisible();
    await expect(filterSummary).toContainText('Electronics');
    await expect(filterSummary).toContainText('Brand A');
  });

  test('should clear all applied filters', async ({ page }) => {
    await page.getByLabel('Category').selectOption('Electronics');
    await page.getByLabel('Brand').selectOption('Brand A');
    await page.getByRole('button', { name: 'Apply Filters' }).click();

    await page.getByRole('button', { name: 'Clear All Filters' }).click();

    const filterSummary = await page.getByRole('heading', { name: 'Applied Filters' });
    await expect(filterSummary).not.toBeVisible();
  });
});
